SourceCode.Declaration:
/// <summary>
/// the <C>METSysOperationDataContractNameAttribute</C> attribute class for data contract name decoration used for sys controller class implementation.
/// </summary>
public class METSysOperationDataContractNameAttribute extends SysAttribute
{
    str dataContractName;

}

Method.Source:
/// <summary>
/// new method to assign value to the local variable.
/// </summary>
/// <param name = "_dataContractName">data contract name value</param>
public void new (str _dataContractName)
{
    super();
    dataContractName = _dataContractName;
}

/// <summary>
/// /parm method to get set data contract name value
/// </summary>
/// <param name = "_dataContractName">data contract name value</param>
/// <returns>data contract name value</returns>
public str parmDataContractName(str _dataContractName = dataContractName)
{
    dataContractName = _dataContractName;

    return dataContractName;
}
